/** Native touch fixture uses fake recognition explicitly. It never opens a microphone. */
final class VoiceHoldChecks {
    interface Condition {boolean get();}
    static int count;static StringBuilder log;static String evidenceTag;
    static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);count++;log.append("PASS ").append(label).append('\n');}
    static void await(Instrumentation test,Condition condition,String label)throws Exception{long until=SystemClock.elapsedRealtime()+20000;boolean[] yes={false};while(SystemClock.elapsedRealtime()<until){test.runOnMainSync(()->yes[0]=condition.get());if(yes[0])return;SystemClock.sleep(80);}throw new AssertionError("native fixture wait: "+label);}
    static Rect bounds(Instrumentation test,View view)throws Exception{Rect[] result={null};test.runOnMainSync(()->{TestViewScreenBounds.Snapshot captured=TestViewScreenBounds.capture(view);log.append("VOICE_SCREEN_BOUNDS ").append(captured).append('\n');result[0]=captured.requireScreen();});return result[0];}
    static View find(View root,String text){if(root instanceof TextView&&text.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View value=find(((ViewGroup)root).getChildAt(i),text);if(value!=null)return value;}return null;}
    static void pointer(Instrumentation test,long down,int action,float x,float y){MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y,0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);try{test.sendPointerSync(e);}finally{e.recycle();}}
    static final class Fixture implements VoiceHoldController.Host {
        final Activity activity;final Dialog dialog;final VoiceHoldTouchSurface surface;final VoiceHoldController controller;final Handler handler=new Handler(Looper.getMainLooper());
        Button space;VoiceHoldOverlay overlay;int spaces,begins,finishes,cancels,commits;String written="BEFORE|";
        long shortSubmissionMillis;final VoiceTouchTrace dialogTrace=new VoiceTouchTrace("dialog"),surfaceTrace=new VoiceTouchTrace("outer-before-surface");
        Fixture(Activity owner){activity=owner;boolean compact=owner.getResources().getConfiguration().orientation==2;surface=new VoiceHoldTouchSurface(owner);controller=new VoiceHoldController(this,(delay,action)->{handler.postDelayed(action,delay);return ()->handler.removeCallbacks(action);},ViewConfiguration.getLongPressTimeout(),ViewConfiguration.get(owner).getScaledTouchSlop());surface.controller(controller);controller.bindInputSession(100);keys();
            dialog=new Dialog(owner){
                @Override public boolean dispatchTouchEvent(MotionEvent event){observe(dialogTrace,event);boolean handled=false;try{handled=super.dispatchTouchEvent(event);return handled;}finally{if(dialogTrace.total<=VoiceTouchTrace.LIMIT)log.append("DISPATCH_RETURN layer=dialog action=").append(event.getActionMasked()).append(" handled=").append(handled).append(" phase=").append(controller.state().phase).append('\n');}}
                @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);log.append("VOICE_WINDOW_FOCUS dialog=").append(focused).append(" uptime=").append(SystemClock.uptimeMillis()).append(" phase=").append(controller.state().phase).append('\n');}
            };
            FrameLayout observed=new FrameLayout(owner){@Override public boolean dispatchTouchEvent(MotionEvent event){observe(surfaceTrace,event);boolean handled=false;try{handled=super.dispatchTouchEvent(event);return handled;}finally{if(surfaceTrace.total<=VoiceTouchTrace.LIMIT)log.append("DISPATCH_RETURN layer=outer-before-surface action=").append(event.getActionMasked()).append(" handled=").append(handled).append(" phase=").append(controller.state().phase).append('\n');}}};
            observed.addView(surface,new FrameLayout.LayoutParams(-1,-1));dialog.setContentView(observed,new ViewGroup.LayoutParams(-1,dp(compact?170:240)));dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);dialog.getWindow().setLayout(-1,-2);dialog.show();dialog.getWindow().setLayout(-1,-2);}
        void observe(VoiceTouchTrace trace,MotionEvent event){trace.record(event.getActionMasked(),event.getDownTime(),event.getEventTime(),SystemClock.uptimeMillis(),event.getPointerCount(),event.getPointerId(event.getActionIndex()),event.getX(),event.getY(),controller.state().phase.name(),surface.hasWindowFocus());if(trace.total<=VoiceTouchTrace.LIMIT){TestViewScreenBounds.Snapshot key=TestViewScreenBounds.capture(space);log.append("DELIVERY_TARGET layer=").append(trace.layer).append(" action=").append(event.getActionMasked()).append(" rawX=").append(event.getRawX()).append(" rawY=").append(event.getRawY()).append(" key={").append(key).append("} rawInsideScreenKey=").append(key.containsRaw(event.getRawX(),event.getRawY())).append('\n');}}
        void describe(String phase){TestViewScreenBounds.Snapshot key=TestViewScreenBounds.capture(space),outer=TestViewScreenBounds.capture(surface);log.append("VOICE_STAGE ").append(phase).append(" uptime=").append(SystemClock.uptimeMillis()).append(" activityFocus=").append(activity.getWindow().getDecorView().hasWindowFocus()).append(" dialogFocus=").append(dialog.getWindow().getDecorView().hasWindowFocus()).append(" surfaceFocus=").append(surface.hasWindowFocus()).append(" key={").append(key).append("} surface={").append(outer).append("} windowType=").append(dialog.getWindow().getAttributes().type).append(" softInputMode=0x").append(Integer.toHexString(dialog.getWindow().getAttributes().softInputMode)).append(" counters spaces=").append(spaces).append(" begins=").append(begins).append(" finishes=").append(finishes).append(" cancels=").append(cancels).append(" phase=").append(controller.state().phase).append('\n');}
        void dumpTrace(){log.append(dialogTrace.summary()).append('\n').append(dialogTrace.history).append(surfaceTrace.summary()).append('\n').append(surfaceTrace.history);}
        int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
        void keys(){overlay=null;surface.removeAllViews();LinearLayout body=new LinearLayout(activity);body.setOrientation(LinearLayout.VERTICAL);TextView label=new TextView(activity);label.setText("语音手势原生触摸测试：识别为假回调，无录音");body.addView(label,new LinearLayout.LayoutParams(-1,0,1));space=new Button(activity);space.setText("测试空格");space.setOnClickListener(v->tapSpace(100));body.addView(space,new LinearLayout.LayoutParams(-1,dp(52)));surface.addView(body,new android.widget.FrameLayout.LayoutParams(-1,-1));surface.spaceKey(space);}
        public boolean beginVoice(VoiceHoldController.Token token){begins++;return true;}
        public void finishVoice(VoiceHoldController.Token token){finishes++;}
        public void cancelVoice(VoiceHoldController.Token token,VoiceHoldController.CancelReason reason){cancels++;}
        public void tapSpace(long session){spaces++;}
        public void commitPreview(VoiceHoldController.Token token,String text,VoiceHoldController.Completion action){commits++;written+=text+(action.appendNewline()?"\n":"");}
        public void discardPreview(VoiceHoldController.Token token,VoiceHoldController.CancelReason reason){}
        public void failed(VoiceHoldController.Token token,String message){throw new AssertionError("unexpected fake recognizer failure");}
        public void update(VoiceHoldController.State state){if(state.showVoiceLayer()){if(overlay==null){surface.spaceKey(null);surface.removeAllViews();overlay=new VoiceHoldOverlay(activity,new VoiceHoldOverlay.Palette(activity.getColor(R.color.paper),activity.getColor(R.color.surface),activity.getColor(R.color.ink),activity.getColor(R.color.muted),activity.getColor(R.color.selected),0xffb13030),activity.getResources().getConfiguration().orientation==2);surface.addView(overlay,new android.widget.FrameLayout.LayoutParams(-1,-1));overlay.coordinateSpace(surface,(token,left,right)->controller.targets(token,left,right));overlay.waitingCancel(token->controller.cancel(token,VoiceHoldController.CancelReason.USER_ABORT));}overlay.setState(state);}else if(overlay!=null)keys();}
    }
    static long down(Instrumentation test,Fixture fixture)throws Exception{Rect space=bounds(test,fixture.space);long now=SystemClock.uptimeMillis();pointer(test,now,MotionEvent.ACTION_DOWN,space.centerX(),space.centerY());return now;}
    static void shortTap(Instrumentation test,Fixture fixture)throws Exception{
        Rect space=bounds(test,fixture.space);long now=SystemClock.uptimeMillis();
        test.runOnMainSync(()->{fixture.describe("before_single_short_tap");Rect current=TestViewScreenBounds.capture(fixture.space).requireScreen();if(!fixture.surface.hasWindowFocus()||!fixture.dialog.getWindow().getDecorView().hasWindowFocus()||!current.equals(space))throw new AssertionError("Native fixture lost focus or changed screen bounds before command; no tap sent");});log.append("COMMAND input-tap once actualScreenKeyBounds=").append(space.toShortString()).append(" point=").append(space.centerX()).append(',').append(space.centerY()).append(" uptime=").append(now).append('\n');
        // UiAutomation injection waits for window/surface animations even with sync=false.
        // One normal OS input command pairs its DOWN/UP without a host roundtrip in between.
        try(android.os.ParcelFileDescriptor descriptor=test.getUiAutomation().executeShellCommand("input tap "+space.centerX()+" "+space.centerY());java.io.InputStream output=new android.os.ParcelFileDescriptor.AutoCloseInputStream(descriptor)){
            byte[] data=new byte[256];int total=0,n;while((n=output.read(data))!=-1){total+=n;if(total>4096)throw new AssertionError("unexpected OS tap command output");}if(total!=0)throw new AssertionError("OS tap command returned diagnostic output");
        }
        fixture.shortSubmissionMillis=SystemClock.uptimeMillis()-now;
        try{await(test,()->fixture.spaces==1,"native OS short Space");}finally{test.runOnMainSync(()->{fixture.describe("after_single_short_tap");log.append("SHORT_TAP command_ms=").append(fixture.shortSubmissionMillis).append(" dialog=").append(fixture.dialogTrace.summary()).append(" outer=").append(fixture.surfaceTrace.summary()).append("; command completion is not delivered UP proof\n");});}
        if(!fixture.dialogTrace.completeShortTap(ViewConfiguration.getLongPressTimeout())||!fixture.surfaceTrace.completeShortTap(ViewConfiguration.getLongPressTimeout()))throw new AssertionError("OS short tap not delivered as a complete DOWN/UP within actual long-press threshold; no retry");
    }
    static long hold(Instrumentation test,Fixture fixture)throws Exception{long now=down(test,fixture);await(test,()->fixture.controller.state().phase==VoiceHoldController.Phase.HOLDING&&fixture.overlay!=null&&find(fixture.overlay,"撤回")!=null,"hold and native layer");await(test,()->find(fixture.overlay,"撤回").getHeight()>0,"target layout");return now;}
    static Rect target(Instrumentation test,Fixture fixture,String text)throws Exception{View[] found={null};test.runOnMainSync(()->found[0]=find(fixture.overlay,text));if(found[0]==null)throw new AssertionError("actual target missing: "+text);return bounds(test,found[0]);}
    static VoiceHoldController.Token token(Instrumentation test,Fixture fixture){VoiceHoldController.Token[] result={null};test.runOnMainSync(()->result[0]=fixture.controller.state().token);return result[0];}
    private static AccessibilityNodeInfo awaitImeNode(String description,boolean isDescription)throws Exception{
        StrictImeWindowQuery.beginObservation(LayoutChecks.auto);long until=SystemClock.elapsedRealtime()+20000;AccessibilityNodeInfo target=null;
        String last="no observation";while(SystemClock.elapsedRealtime()<until){StrictImeWindowQuery.Result result=StrictImeWindowQuery.find(LayoutChecks.auto,AccessibilityWindowInfo.TYPE_INPUT_METHOD,"org.wangshu.ime",description,isDescription);last=result.toString();if(result.node!=null){target=result.node;break;}SystemClock.sleep(150);}
        if(target==null)throw new AssertionError("Actual IME target unavailable; no action sent or retry: "+description+" "+last);return target;
    }
    private static void tapToolbarOnce(String description)throws Exception{
        AccessibilityNodeInfo target=awaitImeNode(description,true);StrictImeToolbarTouch.tap(LayoutChecks.auto,target,description,log);
    }
    static void actualKeyboardLayout(Instrumentation test,Activity activity)throws Exception{
        await(test,()->activity.getWindow().getDecorView().hasWindowFocus(),"editor window restored after fixture");EditText editor=activity.findViewById(R.id.test_editor);test.runOnMainSync(()->{editor.requestFocus();InputMethodManager manager=(InputMethodManager)activity.getSystemService(Context.INPUT_METHOD_SERVICE);manager.restartInput(editor);manager.showSoftInput(editor,InputMethodManager.SHOW_IMPLICIT);});HideChecks.await(LayoutChecks.auto,true);
        AccessibilityNodeInfo space=LayoutChecks.await("空格；按住本地语音，松手结束",true);check(!space.isLongClickable(),"registered OS keyboard Space advertises hold-to-talk and has no old picker long-click action");
        AccessibilityNodeInfo letter=null,shift=null,erase=null;long until=SystemClock.elapsedRealtime()+15000;
        while(SystemClock.elapsedRealtime()<until){for(AccessibilityWindowInfo window:LayoutChecks.auto.getWindows()){AccessibilityNodeInfo root=window.getRoot();if(letter==null){letter=LayoutChecks.find(root,"z",false);if(letter==null)letter=LayoutChecks.find(root,"Z",false);}if(erase==null)erase=LayoutChecks.find(root,"⌫",false);if(shift==null)for(String label:new String[]{"小写","下一字母大写","大写锁定"}){shift=LayoutChecks.find(root,label,true);if(shift!=null)break;}}if(letter!=null&&shift!=null&&erase!=null)break;SystemClock.sleep(150);}
        if(letter==null||shift==null||erase==null)throw new AssertionError("actual keyboard third row unavailable; no inferred bounds");Rect z=new Rect(),s=new Rect(),e=new Rect();letter.getBoundsInScreen(z);shift.getBoundsInScreen(s);erase.getBoundsInScreen(e);check(Math.abs(z.top-s.top)<=4&&Math.abs(z.top-e.top)<=4&&s.right<=z.left&&e.left>=z.right,"actual registered alphabet third row places Shift, z and Backspace together");LayoutChecks.screenshot(test.getTargetContext(),evidenceTag+"/native-voice-hold-keyboard-layout.png");
        tapToolbarOnce("数学");awaitImeNode("字母",true);awaitImeNode("数学语音",true);boolean landscape=activity.getResources().getConfiguration().orientation==2;AccessibilityNodeInfo command=awaitImeNode(landscape?"\\":"\\ 命令",false);Rect r=new Rect();command.getBoundsInScreen(r);check(r.width()>0&&r.height()>0,"real mathematical command entry remains available after removing the fourth alphabet controls row");LayoutChecks.screenshot(test.getTargetContext(),evidenceTag+"/native-voice-hold-math-command.png");tapToolbarOnce("字母");awaitImeNode("数学",true);awaitImeNode("语音",true);awaitImeNode("空格；按住本地语音，松手结束",true);
    }
    static String run(Instrumentation test)throws Exception{
        count=0;log=new StringBuilder();Context context=test.getTargetContext();evidenceTag="voicehold-"+java.util.UUID.randomUUID();java.io.File evidence=new java.io.File(context.getFilesDir(),"test-evidence/"+evidenceTag);if(!evidence.mkdirs())throw new AssertionError("Cannot create isolated voice test evidence");log.append("EVIDENCE ").append(evidenceTag).append("\n");LayoutChecks.auto=test.getUiAutomation();AccessibilityServiceInfo service=LayoutChecks.auto.getServiceInfo();service.flags|=AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;LayoutChecks.auto.setServiceInfo(service);
        Activity activity=test.startActivitySync(new Intent(context,SettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Fixture[] holder={null};Throwable primary=null;
        try{
            test.runOnMainSync(()->holder[0]=new Fixture(activity));Fixture f=holder[0];await(test,()->f.surface.hasWindowFocus()&&f.space.getHeight()>0,"fixture window focus");
            shortTap(test,f);long time;check(f.begins==0,"native Space short touch performs one Space with no fake recognizer start");
            Button[] original={null};test.runOnMainSync(()->original[0]=f.space);time=hold(test,f);check(!original[0].isAttachedToWindow(),"stable outer touch surface survives detachment of the original Space view");Rect left=target(test,f,"撤回"),right=target(test,f,"换行"),surface=bounds(test,f.surface);pointer(test,time,MotionEvent.ACTION_MOVE,left.centerX(),left.centerY());await(test,()->f.controller.state().highlighted==VoiceHoldController.Target.LEFT_DISCARD,"left highlight");check(f.commits==0&&f.finishes==0&&f.cancels==0,"actual left target highlights before UP without executing an action");LayoutChecks.screenshot(context,evidenceTag+"/native-voice-hold-left-preview.png");VoiceHoldController.Token first=token(test,f);test.runOnMainSync(()->f.controller.result(first,"synthetic center"));pointer(test,time,MotionEvent.ACTION_UP,surface.centerX(),surface.bottom-8);await(test,()->f.commits==1,"center final UP");check(f.written.equals("BEFORE|synthetic center")&&f.cancels==0,"final center UP cancels earlier left choice even without a final MOVE; fake result commits once");
            time=hold(test,f);left=target(test,f,"撤回");VoiceHoldController.Token second=token(test,f);test.runOnMainSync(()->f.controller.result(second,"must discard"));pointer(test,time,MotionEvent.ACTION_MOVE,left.centerX(),left.centerY());pointer(test,time,MotionEvent.ACTION_UP,left.centerX(),left.centerY());await(test,()->f.cancels==1,"left release");test.runOnMainSync(()->f.controller.result(second,"late"));check(f.commits==1&&f.written.equals("BEFORE|synthetic center"),"native left release discards only this fake preview; stale result does not change earlier fake text");
            time=hold(test,f);right=target(test,f,"换行");VoiceHoldController.Token third=token(test,f);pointer(test,time,MotionEvent.ACTION_MOVE,right.centerX(),right.centerY());await(test,()->f.controller.state().highlighted==VoiceHoldController.Target.RIGHT_ACTION,"right highlight");LayoutChecks.screenshot(context,evidenceTag+"/native-voice-hold-right-preview.png");pointer(test,time,MotionEvent.ACTION_UP,right.centerX(),right.centerY());await(test,()->f.controller.state().phase==VoiceHoldController.Phase.WAITING_RESULT,"waiting for fake final");check(f.commits==1&&f.finishes==2,"right UP stops once and waits for a later fake final result");LayoutChecks.screenshot(context,evidenceTag+"/native-voice-hold-waiting.png");test.runOnMainSync(()->{f.controller.result(third,"synthetic right");f.controller.result(third,"duplicate");});await(test,()->f.commits==2,"right final");check(f.written.equals("BEFORE|synthetic centersynthetic right\n"),"right release retains fake text and appends one newline without duplicate callback output");
            time=hold(test,f);surface=bounds(test,f.surface);VoiceHoldController.Token fourth=token(test,f);pointer(test,time,MotionEvent.ACTION_CANCEL,surface.centerX(),surface.centerY());await(test,()->f.controller.state().phase==VoiceHoldController.Phase.IDLE,"system cancel");test.runOnMainSync(()->f.controller.result(fourth,"late cancelled"));check(f.commits==2&&f.cancels==2,"native ACTION_CANCEL stops the fake session and makes its late result inert");
            SplitSelection.Snapshot originalSnapshot=new SplitSelection.Snapshot("a𝕏e\u0301",1,1);
            check(WangshuIme.sameVoiceSnapshot(originalSnapshot,new SplitSelection.Snapshot("a𝕏e\u0301",1,1)),"production snapshot equality preserves exact mathematical and combining text");
            check(!WangshuIme.sameVoiceSnapshot(originalSnapshot,new SplitSelection.Snapshot("a𝕏e\u0301",0,0)),"production snapshot guard rejects a moved caret");
            check(!WangshuIme.sameVoiceSnapshot(originalSnapshot,new SplitSelection.Snapshot("a𝕏e\u0301",0,1)),"production snapshot guard rejects a changed selection");
            check(!WangshuIme.sameVoiceSnapshot(originalSnapshot,new SplitSelection.Snapshot("aXe\u0301",1,1))&&!WangshuIme.sameVoiceSnapshot(originalSnapshot,null),"production snapshot guard rejects changed text or unavailable host snapshot");
            check(WangshuIme.voiceCommitVisible(originalSnapshot,"Q",new SplitSelection.Snapshot("aQ𝕏e\u0301",2,2)),"voice completion verifies exact insertion and caret while preserving math suffix");
            check(!WangshuIme.voiceCommitVisible(originalSnapshot,"Q",originalSnapshot),"unchanged host after acknowledged voice request is not silently treated as inserted");
            check(!WangshuIme.voiceCommitVisible(originalSnapshot,"Q",new SplitSelection.Snapshot("aQ𝕏e\u0301",1,1)),"unexpected host caret keeps voice result available for explicit copy without retry");
            test.runOnMainSync(()->{f.controller.clearInputSession();f.dialog.dismiss();});holder[0]=null;actualKeyboardLayout(test,activity);
            return "PASS "+count+" native fixture / snapshot guard / registered keyboard layout checks\n"+log+"Scope: actual Android View pointer dispatch + existing owner-thread controller; recognizer callbacks and output recorder are synthetic. Registered OS keyboard layout/Space semantics separately inspected through native nodes. No microphone, ASR accuracy, registered-IME hold-to-editor commit, user-reference pixel match or real-phone acceptance. Separate VoiceChecks covers actual model WAV inference.\n";
        }catch(Exception|AssertionError failure){
            try{if(holder[0]!=null)test.runOnMainSync(()->{holder[0].describe("failure_before_cleanup");holder[0].dumpTrace();});}catch(Exception|AssertionError unavailable){if(unavailable!=failure)failure.addSuppressed(unavailable);log.append("VOICE_METADATA unavailable=").append(unavailable.getClass().getSimpleName()).append('\n');}
            try{log.append(ImeSelectorDiagnostics.snapshot(LayoutChecks.auto));}catch(Exception|AssertionError unavailable){if(unavailable!=failure)failure.addSuppressed(unavailable);log.append("VOICE_WINDOWS unavailable=").append(unavailable.getClass().getSimpleName()).append('\n');}
            try{LayoutChecks.screenshot(context,evidenceTag+"/native-voice-hold-failure.png");}catch(Exception|AssertionError unavailable){if(unavailable!=failure)failure.addSuppressed(unavailable);log.append("VOICE_SCREENSHOT unavailable=").append(unavailable.getClass().getSimpleName()).append('\n');}
            AssertionError report=new AssertionError("VoiceHold partial count="+count+"\n"+log,failure);primary=report;throw report;
        }finally{Fixture owned=holder[0];TestCleanupSteps.run(()->{if(owned!=null)test.runOnMainSync(()->{owned.controller.clearInputSession();owned.dialog.dismiss();});}).attachOrThrow(primary);}
    }
}
